def build_response(answer, results, triples, evidence_level):
    sources = []
    for item in results:
        sources.append({
            "chunk_id": item.get("chunk_id"),
            "source": item.get("source"),
            "page": item.get("page"),
            "retrieval_reason": item.get("retrieval_reason", "semantic"),
        })
    return {
        "status": "ok",
        "answer": answer,
        "sources": sources,
        "related_triples": triples,
        "evidence_level": evidence_level,
    }


def render_response(payload):
    if payload.get("status") == "error":
        return "Error: {}".format(payload.get("error", "unknown error"))

    lines = [str(payload.get("answer", ""))]
    for source in payload.get("sources", []):
        lines.append(
            "{} p.{} ({})".format(
                source.get("source"),
                source.get("page"),
                source.get("retrieval_reason", "semantic"),
            )
        )
    for triple in payload.get("related_triples", []):
        lines.append(str(triple))
    lines.append("Evidence level: {}".format(payload.get("evidence_level", "")))
    return "\n".join(lines)
